def solve(input_data):
    # Document-specific constants
    # (Constraints for the Author Liaison Agent, chunk 4/10)
    TIER1_LABEL = "Tier 1"
    MAX_PANELISTS_TIER1 = 3  # Session fidelity example: max 3 panelists

    # (Question 2, chunk 7/10)
    BRAND_SCORE_MIN = 9.0  # If below, cannot proceed

    # (Constraints for the Author Liaison Agent, chunk 4/10)
    PAYMENT_SUBMIT_DAYS_AFTER_RETURN = 7  # payment submission timing rule

    # (Question 4 + sponsorship governance mention, chunk 9/10)
    # Financial Lock Date is document-defined; hardcode for tool behavior.
    FINANCIAL_LOCK_DATE = "2026-04-01"

    # (Question 2, chunk 7/10)
    REQUIRED_CLAUSE_CODE = "Force Majeure Clause"

    def parse_date(s):
        if s is None:
            return None
        y, m, d = s.split("-")
        return (int(y), int(m), int(d))

    def date_leq(a, b):
        return parse_date(a) <= parse_date(b)

    def add_days(date_s, days):
        # Simple Gregorian add using Python-free approach via ordinal conversion
        y, m, d = parse_date(date_s)
        mdays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        def is_leap(yy):
            return (yy % 4 == 0 and yy % 100 != 0) or (yy % 400 == 0)
        def to_ordinal(yy, mm, dd):
            # days before year
            days_total = 0
            for yr in range(1, yy):
                days_total += 366 if is_leap(yr) else 365
            # days before month
            for mo in range(1, mm):
                if mo == 2:
                    days_total += 29 if is_leap(yy) else 28
                else:
                    days_total += mdays[mo-1]
            days_total += dd
            return days_total
        def from_ordinal(n):
            yy = 1
            while True:
                dy = 366 if is_leap(yy) else 365
                if n > dy:
                    n -= dy
                    yy += 1
                else:
                    break
            mm = 1
            while True:
                if mm == 2:
                    dm = 29 if is_leap(yy) else 28
                else:
                    dm = mdays[mm-1]
                if n > dm:
                    n -= dm
                    mm += 1
                else:
                    break
            dd = n
            return f"{yy:04d}-{mm:02d}-{dd:02d}"
        return from_ordinal(to_ordinal(y, m, d) + days)

    current_date = input_data["current_date"]
    author = input_data["author"]
    session = input_data["session"]
    marketing = input_data["marketing_request"]
    constraints = input_data["media_constraints"]
    finance = input_data["finance"]
    sponsorship = input_data["sponsorship"]

    blocks = []
    holds = []
    actions = []

    # 1) Session fidelity for Tier 1
    if author.get("tier") == TIER1_LABEL and session.get("revised_panelists") is not None:
        if session["revised_panelists"] > MAX_PANELISTS_TIER1:
            blocks.append("SESSION_FIDELITY_VIOLATION")
            actions.append("ISSUE_SFVR_TO_CURATOR_AND_DIRECTOR")
            if session.get("sponsor_requires_change"):
                actions.append("PROPOSE_ALT_SESSION_OR_SEEK_AUTHOR_AMENDMENT")

    # 2) Media governance: simple constraint parsing from Media Constraint Log lines
    # Document examples include timing restrictions and approval requirements.
    # Implement two constraint types:
    # - "Image Use: No high-res photos before YYYY-MM-DD"
    # - "Quotes: Approval required for all uses"
    asset_type = marketing.get("asset_type")
    date_needed = marketing.get("date_needed")

    for line in constraints:
        if line.startswith("Image Use: No high-res photos before ") and asset_type == "image_high_res":
            cutoff = line.split("before ", 1)[1].strip()
            if date_leq(date_needed, cutoff):
                holds.append("MEDIA_CONSTRAINT_VIOLATION")
                actions.append("HOLD_MARKETING_REQUEST")
                break
        if line.strip() == "Quotes: Approval required for all uses" and asset_type == "quote":
            holds.append("MEDIA_APPROVAL_REQUIRED")
            actions.append("REQUEST_AUTHOR_MEDIA_APPROVAL")
            break

    # 3) Sponsorship governance
    if sponsorship.get("has_incorrect_classifications"):
        # If already past lock date, treat as block; otherwise hold.
        if date_leq(FINANCIAL_LOCK_DATE, current_date):
            blocks.append("SPONSORSHIP_LOCKDATE_BREACH")
        else:
            holds.append("SPONSORSHIP_CLASSIFICATION_CORRECTION")
        actions.append("CORRECT_SPONSORSHIP_CLASSIFICATIONS")

    bcs = sponsorship.get("brand_consistency_score")
    if bcs is not None and bcs < BRAND_SCORE_MIN:
        blocks.append("BRAND_SCORE_TOO_LOW")
        actions.append("RENEGOTIATE_SPONSORSHIP_OR_DECLINE")

    # 4) Compliance governance: required clause before finalization/archiving
    clause_codes = [c.get("code") for c in author.get("contract", {}).get("clauses", [])]
    stage = author.get("contract", {}).get("stage")
    wants_final = stage in ("signed", "finalizing", "archiving")
    if wants_final and REQUIRED_CLAUSE_CODE not in clause_codes:
        blocks.append("MISSING_FORCE_MAJEURE")
        actions.append("ADD_FORCE_MAJEURE_CLAUSE")

    # 5) Finance governance gate
    returned_date = author.get("contract", {}).get("returned_date")
    if wants_final:
        if not finance.get("payment_schedule_submitted"):
            blocks.append("PAYMENT_SCHEDULE_NOT_SUBMITTED")
            actions.append("SUBMIT_PAYMENT_SCHEDULE")
        if not finance.get("finance_reviewed"):
            blocks.append("FINANCE_REVIEW_REQUIRED")
            actions.append("REQUEST_FINANCE_REVIEW")

    # Extension conflict: if extension requested and returned_date exists, check submission deadline
    if finance.get("extension_requested") and returned_date is not None:
        deadline = add_days(returned_date, PAYMENT_SUBMIT_DAYS_AFTER_RETURN)
        # If today is after deadline, it's a conflict; otherwise hold with escalation.
        if date_leq(deadline, current_date):
            blocks.append("PAYMENT_EXTENSION_CONFLICT")
        else:
            holds.append("PAYMENT_EXTENSION_RISK")
        actions.append("ESCALATE_PAYMENT_TIMING_TO_DIRECTOR")

    # Deterministic ordering
    blocks = sorted(set(blocks))
    holds = sorted(set(holds))
    actions = sorted(set(actions))

    overall_status = "PASS"
    if blocks:
        overall_status = "BLOCK"
    elif holds:
        overall_status = "HOLD"

    return {
        "overall_status": overall_status,
        "blocks": blocks,
        "holds": holds,
        "required_actions": actions
    }
